  #define I2C_OLED_SDA 6
  #define I2C_OLED_SCL 7
  // DIY SD Card 
  #define SD_CS_PIN 15
  #define SD_MOSI_PIN 11
  #define SD_SCK_PIN 12
  #define SD_MISO_PIN 13
