% ---------------------------
% Connect to Arduino via Serial
% ---------------------------
clc;
close all;
clear all;
port = "COM11";       % Change to match your Arduino port
baud = 115200;        % Must match Serial.begin() in Arduino
s = serialport(port, baud);
configureTerminator(s, "LF");
flush(s);
cleanupObj = onCleanup(@() cleanupSerial(s));

% ---------------------------
% Wait for Valid Quaternion Data
% ---------------------------
disp('Waiting for valid quaternion data...');
valid_data = false;
while ~valid_data
    try
        line = readline(s);
        disp("From Arduino: " + line);
        q_vals = sscanf(line, '%f,%f,%f,%f');
        if numel(q_vals) == 4
            valid_data = true;
            disp('Valid quaternion data received. Starting visualization...');
        else
            disp('Waiting for quaternion data...');
        end
    catch ME
        disp("Serial read error: " + ME.message);
        pause(0.1);
    end
end

% ---------------------------
% Setup 3D Figure
% ---------------------------
fig = figure;
ax = axes('Parent', fig);
xlim(ax, [-1.2 1.2]);
ylim(ax, [-1.2 1.2]);
zlim(ax, [-1.2 1.2]);
xlabel(ax, 'X'); ylabel(ax, 'Y'); zlabel(ax, 'Z');
title(ax, 'MPU9250 Orientation - 3D Axes');
grid(ax, 'on');
hold(ax, 'on');
view(ax, [45 30]);
set(ax, 'DataAspectRatio', [1 1 1]);
set(ax, 'CameraViewAngleMode', 'manual');
set(ax, 'CameraViewAngle', 7);
axis(ax, 'manual');

% Add a close button
uicontrol('Style', 'pushbutton', 'String', 'Close', ...
    'Position', [20 20 60 20], ...
    'Callback', @(src, event) set(fig, 'UserData', 'close'));

% ---------------------------
% Loop and Read Data
% ---------------------------
try
    while true
        % Check for close button press
        if isfield(get(fig), 'UserData') && strcmp(get(fig, 'UserData'), 'close')
            disp('Close button pressed. Exiting...');
            cleanupSerial(s);
            close(fig);
            break;
        end

        % Read one line of text
        line = readline(s);
        disp("From Arduino: " + line);

        % Parse quaternion from string
        q_vals = sscanf(line, '%f,%f,%f,%f');
        if numel(q_vals) ~= 4
            disp("Skipping invalid data format");
            continue;
        end
        q = quaternion(q_vals(1), q_vals(2), q_vals(3), q_vals(4));

        % Convert to rotation matrix
        R = quat2rotm(q);

        % Extract and normalize rotated axes
        x_axis = R(:,1);  % Red - X
        y_axis = R(:,2);  % Green - Y
        z_axis = R(:,3);  % Blue - Z

        % Clear previous plot and draw new orientation
        cla(ax);
        quiver3(ax, 0, 0, 0, x_axis(1), x_axis(2), x_axis(3), 1, 'r', 'LineWidth', 2); hold(ax, 'on');
        quiver3(ax, 0, 0, 0, y_axis(1), y_axis(2), y_axis(3), 1, 'g', 'LineWidth', 2);
        quiver3(ax, 0, 0, 0, z_axis(1), z_axis(2), z_axis(3), 1, 'b', 'LineWidth', 2);

        % Maintain fixed plot settings
        xlim(ax, [-1.2 1.2]); ylim(ax, [-1.2 1.2]); zlim(ax, [-1.2 1.2]);
        xlabel(ax, 'X'); ylabel(ax, 'Y'); zlabel(ax, 'Z');
        title(ax, 'MPU9250 Orientation - 3D Axes');
        grid(ax, 'on');
        view(ax, [45 30]);
        set(ax, 'DataAspectRatio', [1 1 1]);
        set(ax, 'CameraViewAngle', 7);
        axis(ax, 'manual');
        drawnow;
    end
catch ME
    disp("Error or interruption: " + ME.message);
    cleanupSerial(s);
    close(fig);
end

% Cleanup function to close serial port
function cleanupSerial(s)
    if ~isempty(s) && isvalid(s)
        disp('Closing serial port...');
        flush(s);  % Flush any remaining data
        delete(s); % Explicitly close the serial port
        clear s;   % Clear the variable
    end
end


% ---------------------------
% PROJECT: DeadReckoner - Drift Test Visualizer & Logger
% ---------------------------
clc;
close all;
clear all;

port = "COM11";       % Change to match your Arduino port
baud = 115200;        % Must match Serial.begin() in Arduino

logFileName = '2_Dynamic_Return_to_Zero.csv';
% ---------------------------
% Setup Serial Connection
% ---------------------------
try
    s = serialport(port, baud);
    configureTerminator(s, "LF");
    flush(s);
catch ME
    error('Cannot connect to %s. Ensure it is not open in another app.', port);
end

% ---------------------------
% Setup Data Logger (CSV)
% ---------------------------
logFile = fopen(logFileName, 'w');
if logFile == -1
    error('Cannot create log file. Check folder permissions.');
end
fprintf(logFile, 'Time_s,Qw,Qx,Qy,Qz\n');
logInterval = 1.0; % Log data every 1.0 second to keep file size small
lastLogTime = 0;

% ---------------------------
% Setup 3D Figure
% ---------------------------
% Added CloseRequestFcn to handle the window 'X' button safely
fig = figure('Name', 'MPU9250 Drift Monitor', 'NumberTitle', 'off', ...
             'CloseRequestFcn', @(src, event) set(src, 'UserData', 'close'));
ax = axes('Parent', fig);
xlim(ax, [-1.2 1.2]); ylim(ax, [-1.2 1.2]); zlim(ax, [-1.2 1.2]);
xlabel(ax, 'X'); ylabel(ax, 'Y'); zlabel(ax, 'Z');
title(ax, 'MPU9250 Orientation - Drift Test');
grid(ax, 'on');
hold(ax, 'on');
view(ax, [45 30]);
set(ax, 'DataAspectRatio', [1 1 1]);
set(ax, 'CameraViewAngleMode', 'manual');
set(ax, 'CameraViewAngle', 7);
axis(ax, 'manual');

% Add a close button
uicontrol('Style', 'pushbutton', 'String', 'Stop & Save', ...
    'Position', [20 20 100 30], ...
    'Callback', @(src, event) set(fig, 'UserData', 'close'));

% ---------------------------
% Loop and Read Data
% ---------------------------
disp('Waiting for valid quaternion data...');
startTime = tic; % Start test timer

try
    while true
        % Check if user requested to close (via Button or 'X')
        if isfield(get(fig), 'UserData') && strcmp(get(fig, 'UserData'), 'close')
            disp('Test stopped by user. Executing safe shutdown...');
            break;
        end

        % Only read if data is available (prevents UI freezing)
        if s.NumBytesAvailable > 0
            line = readline(s);

            % Parse quaternion from string
            q_vals = sscanf(line, '%f,%f,%f,%f');
            if numel(q_vals) ~= 4
                continue; % Skip bad frames implicitly
            end
            q = quaternion(q_vals(1), q_vals(2), q_vals(3), q_vals(4));

            % --- Data Logging Logic ---
            currentTime = toc(startTime);
            if currentTime - lastLogTime >= logInterval
                fprintf(logFile, '%.2f,%.6f,%.6f,%.6f,%.6f\n', ...
                        currentTime, q_vals(1), q_vals(2), q_vals(3), q_vals(4));
                lastLogTime = currentTime;

                % Update terminal status without flooding it
                fprintf('Test Running... Time Elapsed: %.0f seconds\n', currentTime);
            end

            % --- Visualization Logic ---
            R = quat2rotm(q);
            x_axis = R(:,1);  % Red - X
            y_axis = R(:,2);  % Green - Y
            z_axis = R(:,3);  % Blue - Z

            cla(ax);
            quiver3(ax, 0, 0, 0, x_axis(1), x_axis(2), x_axis(3), 1, 'r', 'LineWidth', 2); hold(ax, 'on');
            quiver3(ax, 0, 0, 0, y_axis(1), y_axis(2), y_axis(3), 1, 'g', 'LineWidth', 2);
            quiver3(ax, 0, 0, 0, z_axis(1), z_axis(2), z_axis(3), 1, 'b', 'LineWidth', 2);

            xlim(ax, [-1.2 1.2]); ylim(ax, [-1.2 1.2]); zlim(ax, [-1.2 1.2]);
            xlabel(ax, 'X'); ylabel(ax, 'Y'); zlabel(ax, 'Z');
            title(ax, sprintf('MPU9250 Orientation | Time: %.0f s', currentTime));
            grid(ax, 'on');
            view(ax, [45 30]);
            set(ax, 'DataAspectRatio', [1 1 1]);
            set(ax, 'CameraViewAngle', 7);
            axis(ax, 'manual');
            drawnow;
        else
            % Give MATLAB UI time to process button clicks
            pause(0.01);
        end
    end
catch ME
    disp("Error or interruption: " + ME.message);
end

% ---------------------------
% Explicit Cleanup (Guaranteed to run)
% ---------------------------
disp('Closing resources...');

% 1. Close Serial Port safely
if exist('s', 'var') && isvalid(s)
    flush(s);  
    delete(s); 
    clear s;   
    disp('COM Port closed safely.');
end

% 2. Close Log File safely
if exist('logFile', 'var') && logFile ~= -1
    fclose(logFile);
    disp('Log file saved successfully as Static_Drift_Log.csv');
end

% 3. Close the Figure
if exist('fig', 'var') && isgraphics(fig)
    delete(fig);
end

disp('Ready for next run. (No restart needed)');


% =========================================================================
% PROJECT: DeadReckoner - IMU Sensor Fusion
% MODULE: Comprehensive Static Drift Analyzer (With Critical Points)
% AUTHOR: Alireza Sotoodeh
% =========================================================================
clc; clear; close all;

%% 1. Configuration Parameters
filename = '1- Static_Drift_Log.csv'; % Name of your data file
settling_time = 20; % Seconds to ignore at the beginning (Filter convergence)

%% 2. Load Data
disp('--> Loading data from CSV...');
if ~isfile(filename)
    error('File %s not found in the current directory!', filename);
end
data = readtable(filename);

time = data.Time_s;
qw = data.Qw; qx = data.Qx; qy = data.Qy; qz = data.Qz;
N = length(time);

%% 3. Quaternion to Euler Conversion (Roll, Pitch, Yaw)
roll  = zeros(N,1);
pitch = zeros(N,1);
yaw   = zeros(N,1);

for i = 1:N
    w = qw(i); x = qx(i); y = qy(i); z = qz(i);

    % Roll
    roll(i) = atan2(2*(w*x + y*z), 1 - 2*(x^2 + y^2)) * (180/pi);

    % Pitch
    sinp = 2*(w*y - z*x);
    if abs(sinp) >= 1
        pitch(i) = sign(sinp) * 90; 
    else
        pitch(i) = asin(sinp) * (180/pi);
    end

    % Yaw
    yaw(i) = atan2(2*(w*z + x*y), 1 - 2*(y^2 + z^2)) * (180/pi);
end

% Unwrap angles
roll  = unwrap(roll  * pi/180) * 180/pi;
pitch = unwrap(pitch * pi/180) * 180/pi;
yaw   = unwrap(yaw   * pi/180) * 180/pi;

%% 4. Extract Stable Data
stable_idx = time >= settling_time;
t_stable = time(stable_idx);
duration = t_stable(end) - t_stable(1);
duration_min = duration / 60;

% Relative angles (Zeroed out)
r_rel = roll(stable_idx) - roll(find(stable_idx, 1));
p_rel = pitch(stable_idx) - pitch(find(stable_idx, 1));
y_rel = yaw(stable_idx) - yaw(find(stable_idx, 1));

%% 5. Find Critical Points (Max & Min bounds)
[max_r, idx_max_r] = max(r_rel); [min_r, idx_min_r] = min(r_rel);
[max_p, idx_max_p] = max(p_rel); [min_p, idx_min_p] = min(p_rel);
[max_y, idx_max_y] = max(y_rel); [min_y, idx_min_y] = min(y_rel);

% Max Drift (Peak-to-Peak)
drift_R = max_r - min_r;
drift_P = max_p - min_p;
drift_Y = max_y - min_y;

% RMS Noise & Drift Rate
std_R = std(r_rel); std_P = std(p_rel); std_Y = std(y_rel);
rate_R = drift_R / duration_min; rate_P = drift_P / duration_min; rate_Y = drift_Y / duration_min;

%% 6. Print Report
fprintf('\n======================================================\n');
fprintf('       STATIC DRIFT TEST REPORT (ZERO-RATE OFFSET)      \n');
fprintf('======================================================\n');
fprintf('Total Stable Duration: %.2f Seconds (%.2f Min)\n', duration, duration_min);
fprintf('------------------------------------------------------\n');
fprintf('AXIS     | Max Drift (Deg) | Drift Rate (Deg/Min) | RMS Noise (Deg) \n');
fprintf('------------------------------------------------------\n');
fprintf('ROLL (X) | %14.4f | %19.4f | %14.4f \n', drift_R, rate_R, std_R);
fprintf('PITCH(Y) | %14.4f | %19.4f | %14.4f \n', drift_P, rate_P, std_P);
fprintf('YAW  (Z) | %14.4f | %19.4f | %14.4f \n', drift_Y, rate_Y, std_Y);
fprintf('======================================================\n\n');

%% 7. Visualization 1: Main Analysis Figure
figure('Name', 'Static Drift Analysis', 'Color', 'w', 'Position', [50, 100, 1000, 600]);

% Subplot 1: Absolute Raw Angles
subplot(2,1,1);
plot(time, roll, 'r', 'LineWidth', 1.5); hold on;
plot(time, pitch, 'g', 'LineWidth', 1.5);
plot(time, yaw, 'b', 'LineWidth', 1.5);
xline(settling_time, 'k-', 'Settling Time Cutoff', 'LineWidth', 1.5);
title('Absolute Orientation Over Time', 'FontSize', 12, 'FontWeight', 'bold');
xlabel('Time (s)'); ylabel('Angle (Deg)');
legend('Roll', 'Pitch', 'Yaw'); grid on;

% Subplot 2: Relative Drift with Bounds
subplot(2,1,2);
plot(t_stable, r_rel, 'r', 'LineWidth', 1.5); hold on;
plot(t_stable, p_rel, 'g', 'LineWidth', 1.5);
plot(t_stable, y_rel, 'b', 'LineWidth', 1.5);

% Plot light dashed lines for Max/Min boundaries
plot([t_stable(1) t_stable(end)], [max_r max_r], 'r--', 'Color', [1 0 0 0.3]);
plot([t_stable(1) t_stable(end)], [min_r min_r], 'r--', 'Color', [1 0 0 0.3]);
plot([t_stable(1) t_stable(end)], [max_p max_p], 'g--', 'Color', [0 1 0 0.3]);
plot([t_stable(1) t_stable(end)], [min_p min_p], 'g--', 'Color', [0 1 0 0.3]);
plot([t_stable(1) t_stable(end)], [max_y max_y], 'b--', 'Color', [0 0 1 0.3]);
plot([t_stable(1) t_stable(end)], [min_y min_y], 'b--', 'Color', [0 0 1 0.3]);

title('Relative Angle Drift with Max/Min Bounds', 'FontSize', 12, 'FontWeight', 'bold');
xlabel('Time (s)'); ylabel('Drift from Initial (Deg)');
grid on;

%% 8. Visualization 2: Critical Points Figure
figure('Name', 'Critical Drift Points', 'Color', 'w', 'Position', [150, 150, 1000, 450]);
plot(t_stable, r_rel, 'r', 'LineWidth', 1, 'Color', [1 0 0 0.6]); hold on;
plot(t_stable, p_rel, 'g', 'LineWidth', 1, 'Color', [0 1 0 0.6]);
