% =========================================================================
% PROJECT: DeadReckoner - IMU Sensor Fusion
% MODULE: Dynamic Return-to-Zero Analyzer (Anti-Aliasing & True Math)
% AUTHOR: Alireza Sotoodeh
% =========================================================================
clc; clear; close all;

%% 1. Configuration Parameters
filename = '2_Dynamic_Return_to_Zero.csv'; 
startup_ignore_sec = 20; % Strictly ignore first 20s of startup noise
motion_threshold = 3.0; % Threshold for velocity in Deg/sec

%% 2. Load Data
disp('--> Loading data from CSV...');
if ~isfile(filename), error('File %s not found!', filename); end
data = readtable(filename);
time = data.Time_s;
qw = data.Qw; qx = data.Qx; qy = data.Qy; qz = data.Qz;
N = length(time);

%% 3. Quaternion to Euler (Strictly [-180, 180])
roll = zeros(N,1); pitch = zeros(N,1); yaw = zeros(N,1);
for i = 1:N
    w = qw(i); x = qx(i); y = qy(i); z = qz(i);
    roll(i) = atan2(2*(w*x + y*z), 1 - 2*(x^2 + y^2)) * (180/pi);
    sinp = 2*(w*y - z*x);
    if abs(sinp) >= 1, pitch(i) = sign(sinp) * 90; else, pitch(i) = asin(sinp) * (180/pi); end
    yaw(i) = atan2(2*(w*z + x*y), 1 - 2*(y^2 + z^2)) * (180/pi);
end

%% Helper: Circular Difference (Prevents 360 jump errors)
calc_diff = @(a, b) mod((b - a) + 180, 360) - 180;

%% 4. True Angular Velocity & Phase Detection
vel = zeros(N,1);
for i = 2:N
    dt = time(i) - time(i-1);
    if dt == 0, dt = 0.01; end % safety
    vR = calc_diff(roll(i-1), roll(i)) / dt;
    vP = calc_diff(pitch(i-1), pitch(i)) / dt;
    vY = calc_diff(yaw(i-1), yaw(i)) / dt;
    vel(i) = abs(vR) + abs(vP) + abs(vY);
end

% Ignore startup noise
ignore_idx = find(time < startup_ignore_sec, 1, 'last');
if isempty(ignore_idx), ignore_idx = 1; end

is_moving = vel > motion_threshold;
is_moving(1:ignore_idx) = 0; % Mute startup

first_move = find(is_moving, 1, 'first');
last_move = find(is_moving, 1, 'last');

if isempty(first_move)
    first_move = floor(N/3); last_move = floor(2*N/3);
end

% Define precise phase indices
idx_init  = (first_move - 5) : (first_move - 1); % 5 samples right before movement
if idx_init(1) < 1, idx_init = 1:(first_move-1); end
idx_final = (N - 5) : N; % Last 5 samples of the file
idx_dyn   = first_move : last_move;

%% 5. Calculate TRUE Circular Metrics
% Standard Mean for Pitch/Roll
init_R = mean(roll(idx_init)); init_P = mean(pitch(idx_init));
final_R = mean(roll(idx_final)); final_P = mean(pitch(idx_final));

% Circular Mean for Yaw (Crucial for values near +/- 180)
init_Y_rad = mean(exp(1i * yaw(idx_init) * pi/180)); init_Y = angle(init_Y_rad) * 180/pi;
final_Y_rad = mean(exp(1i * yaw(idx_final) * pi/180)); final_Y = angle(final_Y_rad) * 180/pi;

% Return-to-Zero Errors
err_R = abs(calc_diff(init_R, final_R));
err_P = abs(calc_diff(init_P, final_P));
err_Y = abs(calc_diff(init_Y, final_Y));

pct_R = (err_R / 360) * 100; pct_P = (err_P / 360) * 100; pct_Y = (err_Y / 360) * 100;

% Max Deviation (Stress) from Initial Position
dev_R = zeros(length(idx_dyn),1); dev_P = zeros(length(idx_dyn),1); dev_Y = zeros(length(idx_dyn),1);
for k = 1:length(idx_dyn)
    i = idx_dyn(k);
    dev_R(k) = abs(calc_diff(init_R, roll(i)));
    dev_P(k) = abs(calc_diff(init_P, pitch(i)));
    dev_Y(k) = abs(calc_diff(init_Y, yaw(i)));
end
max_dev_R = max(dev_R); max_dev_P = max(dev_P); max_dev_Y = max(dev_Y);

%% 6. Print Report
fprintf('\n===================================================================\n');
fprintf('       TRUE DYNAMIC RETURN-TO-ZERO TEST REPORT (ANTI-ALIAS)          \n');
fprintf('===================================================================\n');
fprintf('Phase 1 (Initial Stable) : %.1f sec to %.1f sec\n', time(idx_init(1)), time(idx_init(end)));
fprintf('Phase 2 (Dynamic Motion) : %.1f sec to %.1f sec\n', time(first_move), time(last_move));
fprintf('Phase 3 (Final Stable)   : %.1f sec to %.1f sec\n', time(idx_final(1)), time(idx_final(end)));
fprintf('-------------------------------------------------------------------\n');
fprintf('AXIS     | Max Deviation(Deg)| Return Error (Deg) | Error (%% FS) \n');
fprintf('-------------------------------------------------------------------\n');
fprintf('ROLL (X) | %17.2f | %18.4f | %10.4f %% \n', max_dev_R, err_R, pct_R);
fprintf('PITCH(Y) | %17.2f | %18.4f | %10.4f %% \n', max_dev_P, err_P, pct_P);
fprintf('YAW  (Z) | %17.2f | %18.4f | %10.4f %% \n', max_dev_Y, err_Y, pct_Y);
fprintf('===================================================================\n\n');

%% 7. Visualization: Timeline without vertical wrap-around lines
figure('Name', 'True Dynamic RTZ Timeline', 'Color', 'w', 'Position', [100, 100, 1000, 500]);
hold on;

% Function to insert NaNs where jumps > 180 occur (hides ugly vertical lines)
break_wrap = @(x,y) insert_nans(x,y);
[t_R, r_plot] = break_wrap(time, roll);
[t_P, p_plot] = break_wrap(time, pitch);
[t_Y, y_plot] = break_wrap(time, yaw);

% Patches
ylim([-190, 190]);
patch([time(idx_init(1)) time(idx_init(end)) time(idx_init(end)) time(idx_init(1))], [-200 -200 200 200], [0.8 0.9 0.8], 'EdgeColor', 'none', 'FaceAlpha', 0.5, 'DisplayName', 'Init Phase');
patch([time(first_move) time(last_move) time(last_move) time(first_move)], [-200 -200 200 200], [0.9 0.8 0.8], 'EdgeColor', 'none', 'FaceAlpha', 0.5, 'DisplayName', 'Dynamic Phase');
patch([time(idx_final(1)) time(idx_final(end)) time(idx_final(end)) time(idx_final(1))], [-200 -200 200 200], [0.8 0.9 0.8], 'EdgeColor', 'none', 'FaceAlpha', 0.5, 'DisplayName', 'Final Phase');

% Plot Broken Lines
plot(t_R, r_plot, 'r', 'LineWidth', 1.5, 'DisplayName', 'Roll (Raw)');
plot(t_P, p_plot, 'g', 'LineWidth', 1.5, 'DisplayName', 'Pitch (Raw)');
plot(t_Y, y_plot, 'b', 'LineWidth', 1.5, 'DisplayName', 'Yaw (Raw)');

title('True Dynamic Motion Timeline (Wrap-Around Corrected)', 'FontSize', 14, 'FontWeight', 'bold');
xlabel('Time (Seconds)', 'FontSize', 11); ylabel('Raw Angle (Degrees)', 'FontSize', 11);
legend('Location', 'best'); grid on; set(gca, 'GridAlpha', 0.3);

%% 8. Bar Chart
figure('Name', 'Return Error', 'Color', 'w', 'Position', [150, 150, 800, 400]);
errors = [err_R, err_P, err_Y]; labels = {'Roll (X)', 'Pitch (Y)', 'Yaw (Z)'};
b = bar(errors, 'FaceColor', 'flat');
b.CData(1,:) = [0.8500 0.3250 0.0980]; b.CData(2,:) = [0.4660 0.6740 0.1880]; b.CData(3,:) = [0.0000 0.4470 0.7410]; 
set(gca, 'xticklabel', labels, 'FontSize', 11, 'FontWeight', 'bold');
ylabel('Absolute Error (Degrees)', 'FontSize', 12); title('True Filter Recovery Error', 'FontSize', 14); grid on;
for i = 1:length(errors), text(i, errors(i), sprintf(' %.3f°', errors(i)), 'HorizontalAlignment', 'center', 'VerticalAlignment', 'bottom', 'FontSize', 12, 'FontWeight', 'bold'); end

%% Helper Function
function [x_out, y_out] = insert_nans(x, y)
    x_out = x; y_out = y;
    jumps = find(abs(diff(y)) > 100);
    for i = length(jumps):-1:1
        idx = jumps(i);
        x_out = [x_out(1:idx); NaN; x_out(idx+1:end)];
        y_out = [y_out(1:idx); NaN; y_out(idx+1:end)];
    end
end


% =========================================================================
% PROJECT: DeadReckoner - IMU Sensor Fusion
% MODULE: Comprehensive Vibration Rejection Analyzer
% AUTHOR: Alireza Sotoodeh
% =========================================================================
clc; clear; close all;

%% 1. Configuration Parameters
filename = '3_Vibration_Rejection.csv'; 
startup_ignore_sec = 15; % Ignore initial filter convergence noise
noise_window_sec = 3.0;  % Moving window size (in seconds) to calculate RMS Noise

%% 2. Load Data
disp('--> Loading data from CSV...');
if ~isfile(filename), error('File %s not found!', filename); end
data = readtable(filename);
time = data.Time_s;
qw = data.Qw; qx = data.Qx; qy = data.Qy; qz = data.Qz;
N = length(time);

%% 3. Quaternion to Euler (Raw [-180, 180])
roll = zeros(N,1); pitch = zeros(N,1); yaw = zeros(N,1);
for i = 1:N
    w = qw(i); x = qx(i); y = qy(i); z = qz(i);
    roll(i) = atan2(2*(w*x + y*z), 1 - 2*(x^2 + y^2)) * (180/pi);
    sinp = 2*(w*y - z*x);
    if abs(sinp) >= 1, pitch(i) = sign(sinp) * 90; else, pitch(i) = asin(sinp) * (180/pi); end
    yaw(i) = atan2(2*(w*z + x*y), 1 - 2*(y^2 + z^2)) * (180/pi);
end

%% Helper: Circular Difference
calc_diff = @(a, b) mod((b - a) + 180, 360) - 180;

%% 4. Baseline Calculation & Auto-Zeroing
% Find the baseline (quiet period) just after startup to "zero out" the angles
base_idx = (time >= startup_ignore_sec) & (time <= startup_ignore_sec + 10);
if sum(base_idx) == 0, base_idx = time >= time(1); end % Fallback

base_R = mean(roll(base_idx));
base_P = mean(pitch(base_idx));
% Circular mean for Yaw to prevent wrap-around bugs near +/-180
base_Y_rad = mean(exp(1i * yaw(base_idx) * pi/180)); 
base_Y = angle(base_Y_rad) * 180/pi;

% Calculate Pure Relative Deviations (Centered at 0)
dev_R = zeros(N,1); dev_P = zeros(N,1); dev_Y = zeros(N,1);
for i = 1:N
    dev_R(i) = calc_diff(base_R, roll(i));
    dev_P(i) = calc_diff(base_P, pitch(i));
    dev_Y(i) = calc_diff(base_Y, yaw(i));
end

%% 5. Rolling Noise (Seismograph Logic)
% Calculate sampling rate roughly
dt = mean(diff(time));
if dt <= 0 || isnan(dt), dt = 0.01; end
window_size = max(3, round(noise_window_sec / dt));

noise_R = movstd(dev_R, window_size);
noise_P = movstd(dev_P, window_size);
noise_Y = movstd(dev_Y, window_size);

%% 6. Calculate Metrics (Ignoring Startup)
valid_idx = time >= startup_ignore_sec;

% Max Positive Spikes
max_pos_R = max(dev_R(valid_idx));
max_pos_P = max(dev_P(valid_idx));
max_pos_Y = max(dev_Y(valid_idx));

% Max Negative Spikes
max_neg_R = min(dev_R(valid_idx));
max_neg_P = min(dev_P(valid_idx));
max_neg_Y = min(dev_Y(valid_idx));

% Peak-to-Peak Swing (Total Vibration Amplitude)
p2p_R = max_pos_R - max_neg_R;
p2p_P = max_pos_P - max_neg_P;
p2p_Y = max_pos_Y - max_neg_Y;

% Overall RMS Noise
rms_R = std(dev_R(valid_idx));
rms_P = std(dev_P(valid_idx));
rms_Y = std(dev_Y(valid_idx));

%% 7. Print Report
fprintf('\n=======================================================================\n');
fprintf('               VIBRATION REJECTION TEST REPORT                         \n');
fprintf('=======================================================================\n');
fprintf('Test Duration: %.1f sec (First %d sec ignored for startup)\n', time(end), startup_ignore_sec);
fprintf('-----------------------------------------------------------------------\n');
fprintf('AXIS     | Max Positive | Max Negative | Peak-to-Peak | Overall RMS \n');
fprintf('         | Spike (Deg)  | Spike (Deg)  | Swing (Deg)  | Noise (Deg) \n');
fprintf('-----------------------------------------------------------------------\n');
fprintf('ROLL (X) | %12.3f | %12.3f | %12.3f | %11.3f \n', max_pos_R, max_neg_R, p2p_R, rms_R);
fprintf('PITCH(Y) | %12.3f | %12.3f | %12.3f | %11.3f \n', max_pos_P, max_neg_P, p2p_P, rms_P);
fprintf('YAW  (Z) | %12.3f | %12.3f | %12.3f | %11.3f \n', max_pos_Y, max_neg_Y, p2p_Y, rms_Y);
fprintf('=======================================================================\n\n');

%% 8. Visualization 1: Relative Deviation & Seismograph
figure('Name', 'Vibration Analysis', 'Color', 'w', 'Position', [50, 50, 1000, 700]);

% Subplot 1: Pure Angular Deviation
subplot(2,1,1);
plot(time, dev_R, 'r', 'LineWidth', 1.5, 'DisplayName', 'Roll Deviation'); hold on;
plot(time, dev_P, 'g', 'LineWidth', 1.5, 'DisplayName', 'Pitch Deviation');
plot(time, dev_Y, 'b', 'LineWidth', 1.5, 'DisplayName', 'Yaw Deviation');
xline(startup_ignore_sec, 'k--', 'Filter Ready', 'LineWidth', 1.5);
yline(0, 'k-', 'HandleVisibility', 'off'); % Center line

% Set dynamic Y-limits to zoom in on the vibrations
max_dev = max([p2p_R, p2p_P, p2p_Y]) / 2;
ylim([-(max_dev + 1), (max_dev + 1)]);

title('Angular Deviation During Mechanical Shocks (Zero-Centered)', 'FontSize', 12, 'FontWeight', 'bold');
xlabel('Time (s)'); ylabel('Deviation from Baseline (Deg)');
legend('Location', 'best'); grid on; set(gca, 'GridAlpha', 0.4);

% Subplot 2: Rolling RMS Noise (Seismograph)
subplot(2,1,2);
plot(time, noise_R, 'r', 'LineWidth', 1.2, 'DisplayName', 'Roll Noise'); hold on;
plot(time, noise_P, 'g', 'LineWidth', 1.2, 'DisplayName', 'Pitch Noise');
plot(time, noise_Y, 'b', 'LineWidth', 1.2, 'DisplayName', 'Yaw Noise');
xline(startup_ignore_sec, 'k--', 'LineWidth', 1.5, 'HandleVisibility', 'off');

title('Vibration Intensity over Time (Rolling RMS Noise)', 'FontSize', 12, 'FontWeight', 'bold');
xlabel('Time (s)'); ylabel('Noise Level (Deg)');
legend('Location', 'best'); grid on; set(gca, 'GridAlpha', 0.4);

%% 9. Visualization 2: Max Vibration Swing (Bar Chart)
figure('Name', 'Vibration Swing Analysis', 'Color', 'w', 'Position', [150, 150, 700, 400]);

swings = [p2p_R, p2p_P, p2p_Y];
labels = {'Roll (X)', 'Pitch (Y)', 'Yaw (Z)'};

b = bar(swings, 'FaceColor', 'flat');
b.CData(1,:) = [0.8500 0.3250 0.0980]; 
b.CData(2,:) = [0.4660 0.6740 0.1880]; 
b.CData(3,:) = [0.0000 0.4470 0.7410]; 

set(gca, 'xticklabel', labels, 'FontSize', 11, 'FontWeight', 'bold');
ylabel('Peak-to-Peak Swing (Degrees)', 'FontSize', 12);
title('Maximum Angular Fluctuation During Physical Impacts', 'FontSize', 14);
grid on; set(gca, 'GridAlpha', 0.3);

for i = 1:length(swings)
    text(i, swings(i), sprintf(' %.3f°', swings(i)), ...
        'HorizontalAlignment', 'center', 'VerticalAlignment', 'bottom', ...
        'FontSize', 12, 'FontWeight', 'bold');
end

import os import glob import struct import pandas as pd import matplotlib.pyplot as plt import questionary
# ========================================================================= # DeadReckoner Advanced Binary Decoder & Analyzer # Version: 1.0 # Architecture: 45-Byte Sequential Parsing # =========================================================================
class BinaryDecoder: FRAME_SIZE = 45 HEADER_FMT = '< I Q B' # 4 bytes (uint32), 8 bytes (uint64), 1 byte (uint8) IMU_FMT = '< 4f 3f f' # 32 bytes: 4x float (Quat), 3x float (Accel), 1x float (Temp)
FLAG_IMU = 0x00 FLAG_TAG = 0x01 FLAG_GAP = 0xAA FLAG_GPS = 0xBB
@classmethod def parse_file(cls, filepath): data = [] dropped_frames_total = 0 last_seq = -1
try: with open(filepath, 'rb') as f: while True: chunk = f.read(cls.FRAME_SIZE) if len(chunk) < cls.FRAME_SIZE: break
header_bytes = chunk[:13] payload_bytes = chunk[13:]
frame_seq, timestamp, event_flag = struct.unpack(cls.HEADER_FMT, header_bytes)
if last_seq != -1 and frame_seq > last_seq + 1: dropped_frames_total += (frame_seq - last_seq - 1) last_seq = frame_seq
if event_flag in (cls.FLAG_IMU, cls.FLAG_TAG, cls.FLAG_GAP): q0, q1, q2, q3, ax, ay, az, temp = struct.unpack(cls.IMU_FMT, payload_bytes)
data.append({ 'Frame_Sequence': frame_seq, 'Timestamp_us': timestamp, 'Timestamp_s': timestamp / 1000000.0, 'Event_Flag': hex(event_flag), 'Q_w': q0, 'Q_x': q1, 'Q_y': q2, 'Q_z': q3, 'Accel_X': ax, 'Accel_Y': ay, 'Accel_Z': az, 'Temperature_C': temp }) else: pass
except Exception as e: print(f"Error reading {filepath}: {e}")
return data, dropped_frames_total
class DataScanner: @staticmethod def scan_missions(directory="."): missions = {} all_bins = glob.glob(os.path.join(directory, "*.BIN"))
for file in all_bins: filename = os.path.basename(file)
if filename.startswith("DR_LOG_") and len(filename) == 14: mission_id = filename[7:10] if mission_id not in missions: missions[mission_id] = [] missions[mission_id].append(file)
elif len(filename) == 10 and filename[:6].isdigit(): mission_id = filename[:3] if mission_id not in missions: missions[mission_id] = [] missions[mission_id].append(file)
for m_id in missions: missions[m_id].sort()
return missions
class DataExporter: @staticmethod def export_csv(df, output_name): df.to_csv(f"{output_name}.csv", index=False) print(f"[+] Saved: {output_name}.csv")
@staticmethod def export_excel(df, output_name): df.to_excel(f"{output_name}.xlsx", index=False) print(f"[+] Saved: {output_name}.xlsx")
@staticmethod def generate_report(df, dropped_count, files_merged, output_name): total_time = df['Timestamp_s'].iloc[-1] - df['Timestamp_s'].iloc[0] if not df.empty else 0 tag_count = len(df[df['Event_Flag'] == '0x1']) gap_count = len(df[df['Event_Flag'] == '0xaa'])
report = ( f"=========================================\n" f" MISSION DIAGNOSTIC REPORT\n" f"=========================================\n" f"Mission ID : {output_name}\n" f"Fragments Merged : {files_merged}\n" f"Total Frames : {len(df)}\n" f"Mission Duration : {total_time:.2f} Seconds\n" f"-----------------------------------------\n" f"HARDWARE INTEGRITY\n" f"Silent Drops : {dropped_count} Frames\n" f"SD Recovery Gaps : {gap_count} Events\n" f"User Tags : {tag_count} Waypoints\n" f"-----------------------------------------\n" f"THERMAL & SENSOR DATA\n" f"Max Temperature : {df['Temperature_C'].max():.2f} °C\n" f"Min Temperature : {df['Temperature_C'].min():.2f} °C\n" f"=========================================\n" )
with open(f"{output_name}_Report.txt", "w") as f: f.write(report) print(f"[+] Saved: {output_name}_Report.txt")
@staticmethod def plot_data(df, output_name): fig, axs = plt.subplots(3, 1, figsize=(12, 10), sharex=True) fig.suptitle(f'Mission Profile: {output_name}', fontsize=16)
axs[0].plot(df['Timestamp_s'], df['Accel_X'], label='Acc X') axs[0].plot(df['Timestamp_s'], df['Accel_Y'], label='Acc Y') axs[0].plot(df['Timestamp_s'], df['Accel_Z'], label='Acc Z') axs[0].set_ylabel('Acceleration (G)') axs[0].legend(loc='upper right') axs[0].grid(True)
axs[1].plot(df['Timestamp_s'], df['Q_w'], label='Qw') axs[1].plot(df['Timestamp_s'], df['Q_x'], label='Qx') axs[1].plot(df['Timestamp_s'], df['Q_y'], label='Qy') axs[1].plot(df['Timestamp_s'], df['Q_z'], label='Qz') axs[1].set_ylabel('Quaternions') axs[1].legend(loc='upper right') axs[1].grid(True)
axs[2].plot(df['Timestamp_s'], df['Temperature_C'], color='red') axs[2].set_ylabel('Temperature (°C)') axs[2].set_xlabel('Time (Seconds)') axs[2].grid(True)
tags = df[df['Event_Flag'] == '0x1'] for _, tag in tags.iterrows(): for ax in axs: ax.axvline(x=tag['Timestamp_s'], color='green', linestyle='--', alpha=0.5)
gaps = df[df['Event_Flag'] == '0xaa'] for _, gap in gaps.iterrows(): for ax in axs: ax.axvline(x=gap['Timestamp_s'], color='red', linestyle='-', linewidth=2, alpha=0.7)
plt.tight_layout() plt.savefig(f"{output_name}_Plot.png", dpi=300) print(f"[+] Saved: {output_name}_Plot.png") plt.show()
