% Script to parse DR_LOG.BIN from ESP32-S3 Dead Reckoning System
clear; clc; close all;

filename = 'DR_LOG.BIN';
fid = fopen(filename, 'rb');

if fid == -1
    error('Could not open DR_LOG.BIN. Make sure it is in the same directory.');
end

% Get file size to calculate number of frames
fseek(fid, 0, 'eof');
fileSize = ftell(fid);
fseek(fid, 0, 'bof');

frameSizeBytes = 48; % 4(uint32) + 16(4*float) + 12(3*float) + 16(2*double)
numFrames = floor(fileSize / frameSizeBytes);

fprintf('Found %d frames in the log file.\n', numFrames);

% Preallocate arrays for speed
timestamp = zeros(numFrames, 1, 'uint32');
q = zeros(numFrames, 4, 'single');
accel = zeros(numFrames, 3, 'single');
gps = zeros(numFrames, 2, 'double');

% Read the binary file frame by frame
for i = 1:numFrames
    timestamp(i) = fread(fid, 1, 'uint32');
    q(i, :) = fread(fid, 4, 'single');
    accel(i, :) = fread(fid, 3, 'single');
    gps(i, :) = fread(fid, 2, 'double');
end

fclose(fid);

% --- Visualization ---
% Convert timestamp from milliseconds to seconds
time_sec = double(timestamp - timestamp(1)) / 1000;

figure('Name', 'DeadReckoner Sensor Logs', 'Position', [100, 100, 1000, 600]);

% Plot Quaternions
subplot(2,1,1);
plot(time_sec, q(:,1), 'k', 'LineWidth', 1.5); hold on;
plot(time_sec, q(:,2), 'r');
plot(time_sec, q(:,3), 'g');
plot(time_sec, q(:,4), 'b');
title('Quaternion Data over Time');
legend('Qw', 'Qx', 'Qy', 'Qz');
xlabel('Time (s)');
ylabel('Value');
grid on;

% Plot Linear Acceleration
subplot(2,1,2);
plot(time_sec, accel(:,1), 'r', 'LineWidth', 1); hold on;
plot(time_sec, accel(:,2), 'g', 'LineWidth', 1);
plot(time_sec, accel(:,3), 'b', 'LineWidth', 1);
title('Linear Acceleration (g)');
legend('Acc X', 'Acc Y', 'Acc Z');
xlabel('Time (s)');
ylabel('Acceleration');
grid on;


% =========================================================================
% PROJECT: DeadReckoner - Data Extraction & Diagnostic Pipeline
% DESCRIPTION: Parses binary .BIN logs from ESP32, decodes the 49-byte 
% packed struct, identifies dropped frames, SD failures, and User Tags.
% =========================================================================

clc; clear; close all;

% --- CONFIGURATION ---
% Explicitly defined 49 bytes to match __attribute__((packed)) in ESP32
FRAME_SIZE = 49; 

% Find all .BIN files in the current MATLAB directory
filePattern = fullfile(pwd, '*.BIN');
binFiles = dir(filePattern);

if isempty(binFiles)
    fprintf('CRITICAL: No .BIN files found in %s\n', pwd);
    return;
end

for k = 1:length(binFiles)
    baseFileName = binFiles(k).name;
    fprintf('\n=======================================\n');
    fprintf('Processing Log File: %s\n', baseFileName);

    % 1. Open and Read Raw Binary Data
    fid = fopen(baseFileName, 'rb');
    if fid == -1
        warning('Could not open %s', baseFileName);
        continue;
    end
    rawData = fread(fid, inf, '*uint8');
    fclose(fid);

    % 2. Validate Data Integrity
    numFrames = floor(length(rawData) / FRAME_SIZE);
    if numFrames == 0
        warning('File %s is empty or corrupted.', baseFileName);
        continue;
    end

    % 3. Preallocate Memory for Speed
    frame_seq = zeros(numFrames, 1, 'uint32');
    q = zeros(numFrames, 4, 'single');
    acc = zeros(numFrames, 3, 'single');
    gps = zeros(numFrames, 2, 'double');
    event_flag = zeros(numFrames, 1, 'uint8');

    % 4. Byte-Level Decoding (Endian-safe)
    for i = 1:numFrames
        offset = (i - 1) * FRAME_SIZE;

        frame_seq(i) = typecast(rawData(offset+1 : offset+4), 'uint32');
        q(i, 1) = typecast(rawData(offset+5 : offset+8), 'single');    % Qw
        q(i, 2) = typecast(rawData(offset+9 : offset+12), 'single');   % Qx
        q(i, 3) = typecast(rawData(offset+13 : offset+16), 'single');  % Qy
        q(i, 4) = typecast(rawData(offset+17 : offset+20), 'single');  % Qz

        acc(i, 1) = typecast(rawData(offset+21 : offset+24), 'single'); % Acc X
        acc(i, 2) = typecast(rawData(offset+25 : offset+28), 'single'); % Acc Y
        acc(i, 3) = typecast(rawData(offset+29 : offset+32), 'single'); % Acc Z

        gps(i, 1) = typecast(rawData(offset+33 : offset+40), 'double'); % Lat
        gps(i, 2) = typecast(rawData(offset+41 : offset+48), 'double'); % Lng

        event_flag(i) = rawData(offset+49);
    end

    % --- DIAGNOSTICS & ANALYSIS ---

    % A. Find SD Card Failures (Gap Frames marked with 0xAA / 170)
    gap_indices = find(event_flag == 170);

    % B. Find User Waypoint Tags (Marked with 1)
    tag_indices = find(event_flag == 1);

    % C. Detect Queue Overflows (Dropped Frames)
    % Exclude the 0xFFFFFFFF gap frames to calculate pure sensor jumps
    valid_seq_idx = find(event_flag ~= 170);
    valid_seq = double(frame_seq(valid_seq_idx));

    seq_jumps = diff(valid_seq);
    drop_instances = find(seq_jumps > 1);
    total_dropped_frames = sum(seq_jumps(drop_instances) - 1);

    % Print Analysis to Console
    fprintf('-> Total Recorded Frames: %d\n', numFrames);
    fprintf('-> Number of SD Card Disconnects (Gaps): %d\n', length(gap_indices));
    fprintf('-> User Waypoint Tags Pressed: %d\n', length(tag_indices));
    fprintf('-> Dropped Sensor Frames (Queue Overflows): %d\n', total_dropped_frames);
    if (total_dropped_frames > 0)
        fprintf('   [!] WARNING: You have missing IMU data. Check SPI speed or Queue Size.\n');
    end

    % --- ADVANCED VISUALIZATION ---
    fig = figure('Name', ['Data Analysis: ', baseFileName], 'Position', [100, 100, 1200, 800]);

    % Subplot 1: Linear Acceleration & Events
    subplot(3, 1, 1);
    hold on; grid on;
    plot(acc(:,1), 'r', 'DisplayName', 'Acc X');
    plot(acc(:,2), 'g', 'DisplayName', 'Acc Y');
    plot(acc(:,3), 'b', 'DisplayName', 'Acc Z');

    % Plot User Tags (Yellow Triangles)
    if ~isempty(tag_indices)
        plot(tag_indices, acc(tag_indices, 3), 'k^', 'MarkerFaceColor', 'y', 'MarkerSize', 8, 'DisplayName', 'User Tag (Event)');
    end

    % Plot SD Card Gaps (Vertical Red Lines)
    if ~isempty(gap_indices)
        for g = 1:length(gap_indices)
            xline(gap_indices(g), 'm--', 'LineWidth', 2, 'HandleVisibility', 'off');
        end
        plot(NaN, NaN, 'm--', 'DisplayName', 'SD Recovery Gap (0xAA)'); % Dummy plot for legend
    end
    title('3D Linear Acceleration (g) with Hardware Events');
    ylabel('Acceleration (g)');
    legend('Location', 'best');

    % Subplot 2: Madgwick Quaternions
    subplot(3, 1, 2);
    hold on; grid on;
    plot(q(:,1), 'k', 'LineWidth', 1.5, 'DisplayName', 'Qw');
    plot(q(:,2), 'r', 'DisplayName', 'Qx');
    plot(q(:,3), 'g', 'DisplayName', 'Qy');
    plot(q(:,4), 'b', 'DisplayName', 'Qz');
    title('Orientation (Madgwick Quaternions)');
    ylabel('Value');
    legend('Location', 'best');

    % Subplot 3: Data Integrity (Sequence Jumps)
    subplot(3, 1, 3);
    hold on; grid on;
    plot(valid_seq_idx, valid_seq, 'b.', 'DisplayName', 'Received Sequences');
    if ~isempty(drop_instances)
        % Mark the exact points where a frame jump occurred
        plot(valid_seq_idx(drop_instances), valid_seq(drop_instances), 'ro', 'MarkerSize', 6, 'MarkerFaceColor', 'r', 'DisplayName', 'Queue Overflow Point');
    end
    title(sprintf('Data Integrity Monitor (Total Dropped Frames: %d)', total_dropped_frames));
    xlabel('Time (Frame Index @ 100Hz)'); ylabel('Frame Sequence Number');
    legend('Location', 'northwest');
end


% Last Edit: 2026-06-12 19:30:00  
% Reason for Last Edit: Implemented Relational Sequence Chaining (Greedy Stitcher) 
% to automatically merge crashed SD sessions without needing an RTC.

clc; clear; close all;

% --- HARDWARE ARCHITECTURE CONFIGURATION ---
FRAME_SIZE = 33; % Exact packed union struct size from ESP32

% 1. Scan for all Binary Logs
filePattern = fullfile(pwd, '*.BIN');
binFiles = dir(filePattern);

if isempty(binFiles)
    fprintf('CRITICAL ERROR: No .BIN log files discovered in directory: %s\n', pwd);
    return;
end

fprintf('\n==================================================\n');
fprintf('PHASE 1: METADATA EXTRACTION & RELATIONAL CHAINING\n');
fprintf('==================================================\n');

% 2. Extract Metadata from all files
fileMeta = struct('name', {}, 'data', {}, 'start_seq', {}, 'end_seq', {}, 'processed', {});

validFileCount = 0;
for k = 1:length(binFiles)
    baseFileName = binFiles(k).name;
    fid = fopen(baseFileName, 'rb');
    if fid == -1, continue; end

    rawData = fread(fid, inf, '*uint8');
    fclose(fid);

    numFrames = floor(length(rawData) / FRAME_SIZE);
    if numFrames < 2 % Ignore completely empty or corrupt fragments
        fprintf('  [!] Ignoring %s: Too small to contain valid sequence.\n', baseFileName);
        continue; 
    end

    validFileCount = validFileCount + 1;
    fileMeta(validFileCount).name = baseFileName;
    fileMeta(validFileCount).data = rawData;
    fileMeta(validFileCount).processed = false;

    % Read very first frame sequence (Bytes 1-4)
    fileMeta(validFileCount).start_seq = typecast(rawData(1:4), 'uint32');
    % Read very last frame sequence (Last 33 bytes, Bytes 1-4)
    lastFrameOffset = (numFrames - 1) * FRAME_SIZE;
    fileMeta(validFileCount).end_seq = typecast(rawData(lastFrameOffset+1 : lastFrameOffset+4), 'uint32');
end

% 3. Greedy Stitching Algorithm (The "RTC Emulator")
sessions = {};
sessionCount = 0;

while any(~[fileMeta.processed])
    sessionCount = sessionCount + 1;

    % Find the unprocessed file with the absolute minimum start_seq (Usually a boot-up)
    unproc_idx = find(~[fileMeta.processed]);
    [~, min_idx] = min([fileMeta(unproc_idx).start_seq]);
    curr_idx = unproc_idx(min_idx);

    current_data = fileMeta(curr_idx).data;
    current_end = fileMeta(curr_idx).end_seq;
    fileMeta(curr_idx).processed = true;

    session_chain = {fileMeta(curr_idx).name};

    % Search for crashed fragments that belong to this session
    while true
        unproc = find(~[fileMeta.processed]);
        if isempty(unproc), break; end

        % Candidates MUST start after the current end sequence
        candidates = unproc([fileMeta(unproc).start_seq] > current_end);
        if isempty(candidates), break; end

        % Pick the candidate that starts closest to our end point
        [~, c_min_idx] = min([fileMeta(candidates).start_seq]);
        next_idx = candidates(c_min_idx);

        % Safety Check: If the gap is impossibly huge (e.g. > 10 mins of dropped frames = 60,000)
        % It probably belongs to a completely different test on a different day!
        if fileMeta(next_idx).start_seq - current_end > 100000 
            break; 
        end

        % Stitch it!
        current_data = [current_data; fileMeta(next_idx).data];
        current_end = fileMeta(next_idx).end_seq;
        fileMeta(next_idx).processed = true;
        session_chain{end+1} = fileMeta(next_idx).name;
    end

    sessions{sessionCount}.data = current_data;
    sessions{sessionCount}.chain = session_chain;

    fprintf(' -> Successfully Built Session %d: ', sessionCount);
    fprintf('%s ', session_chain{:});
    fprintf('\n');
end

fprintf('\n==================================================\n');
fprintf('PHASE 2: PAYLOAD DECODING & DIAGNOSTICS\n');
fprintf('==================================================\n');

% 4. Decode and Plot each merged Session
for s = 1:length(sessions)
    rawData = sessions{s}.data;
    chainNames = strjoin(sessions{s}.chain, ' + ');

    numFrames = floor(length(rawData) / FRAME_SIZE);

    frame_seq = zeros(numFrames, 1, 'uint32');
    event_flag = zeros(numFrames, 1, 'uint8');
    q = nan(numFrames, 4, 'single');        
    acc = nan(numFrames, 3, 'single');      

    for i = 1:numFrames
        offset = (i - 1) * FRAME_SIZE;

        frame_seq(i) = typecast(rawData(offset+1 : offset+4), 'uint32');
        event_flag(i) = rawData(offset+5);

        if event_flag(i) == 0 || event_flag(i) == 1
            q(i, 1) = typecast(rawData(offset+6  : offset+9),  'single'); 
            q(i, 2) = typecast(rawData(offset+10 : offset+13), 'single'); 
            q(i, 3) = typecast(rawData(offset+14 : offset+17), 'single'); 
            q(i, 4) = typecast(rawData(offset+18 : offset+21), 'single'); 

            acc(i, 1) = typecast(rawData(offset+22 : offset+25), 'single'); 
            acc(i, 2) = typecast(rawData(offset+26 : offset+29), 'single'); 
            acc(i, 3) = typecast(rawData(offset+30 : offset+33), 'single'); 
        end
    end

    gap_indices = find(event_flag == 170);
    tag_indices = find(event_flag == 1);

    valid_imu_idx = find(event_flag == 0 | event_flag == 1);
    valid_seq = double(frame_seq(valid_imu_idx));

    seq_jumps = diff(valid_seq);
    drop_instances = find(seq_jumps > 1);
    total_dropped_frames = sum(seq_jumps(drop_instances) - 1);

    fprintf('\n[SESSION %d STATS] (%s)\n', s, chainNames);
    fprintf('  - Total Merged Frames: %d\n', numFrames);
    fprintf('  - SD Card Recovery Gaps: %d\n', length(gap_indices));
    fprintf('  - Missing Frames (Queue Drops): %d\n', total_dropped_frames);

    % --- PLOTTING ---
    figure('Name', sprintf('Session %d Analysis [%s]', s, chainNames), 'Position', [150+(s*20), 100+(s*20), 1100, 750]);

    subplot(3, 1, 1); hold on; grid on;
    plot(acc(:,1), 'r', 'DisplayName', 'Acc X');
    plot(acc(:,2), 'g', 'DisplayName', 'Acc Y');
    plot(acc(:,3), 'b', 'DisplayName', 'Acc Z');
    if ~isempty(tag_indices)
        plot(tag_indices, acc(tag_indices, 3), 'k^', 'MarkerFaceColor', 'y', 'MarkerSize', 7, 'DisplayName', 'Waypoint');
    end
    if ~isempty(gap_indices)
        for g = 1:length(gap_indices), xline(gap_indices(g), 'm--', 'LineWidth', 1.8, 'HandleVisibility', 'off'); end
        plot(NaN, NaN, 'm--', 'LineWidth', 1.8, 'DisplayName', 'Recovery Gap');
    end
    title(sprintf('SESSION %d: 3-Axis Acceleration', s)); ylabel('g'); legend('Location', 'best');

    subplot(3, 1, 2); hold on; grid on;
    plot(q(:,1), 'k', 'DisplayName', 'Qw'); plot(q(:,2), 'r', 'DisplayName', 'Qx');
    plot(q(:,3), 'g', 'DisplayName', 'Qy'); plot(q(:,4), 'b', 'DisplayName', 'Qz');
    title('Orientation (Madgwick)'); ylabel('Value'); legend('Location', 'best');

    subplot(3, 1, 3); hold on; grid on;
    plot(valid_imu_idx, valid_seq, 'b-', 'DisplayName', 'Stream');
    if ~isempty(drop_instances)
        plot(valid_imu_idx(drop_instances), valid_seq(drop_instances), 'ro', 'MarkerFaceColor', 'r', 'DisplayName', 'Data Drop');
    end
    title(sprintf('Frame Continuity (Lost: %d)', total_dropped_frames)); xlabel('Merged File Row Index'); ylabel('Frame Seq');
end


% Last Edit: 2026-06-12 21:00:00  
% Reason for Last Edit: Replaced strict sequence matching with Absolute Distance Minimizer. 
% Added Garbage-Frame filter to automatically discard corrupted tail bytes from hot-plugged SD cards.

clc; clear; close all;

% --- HARDWARE ARCHITECTURE CONFIGURATION ---
FRAME_SIZE = 33; 

filePattern = fullfile(pwd, '*.BIN');
binFiles = dir(filePattern);

if isempty(binFiles)
    fprintf('CRITICAL ERROR: No .BIN log files discovered in directory: %s\n', pwd);
    return;
end

fprintf('\n==================================================\n');
fprintf('PHASE 1: METADATA EXTRACTION & GARBAGE FILTERING\n');
fprintf('==================================================\n');

fileMeta = struct('name', {}, 'data', {}, 'start_seq', {}, 'end_seq', {}, 'processed', {});
validFileCount = 0;

for k = 1:length(binFiles)
    baseFileName = binFiles(k).name;
    fid = fopen(baseFileName, 'rb');
    if fid == -1, continue; end

    rawData = fread(fid, inf, '*uint8');
    fclose(fid);

    numFrames = floor(length(rawData) / FRAME_SIZE);
    if numFrames < 2, continue; end

    % Extract all sequences to find the TRUE start and end, avoiding corrupted tails
    f_seq = zeros(numFrames, 1, 'double');
    e_flag = zeros(numFrames, 1, 'uint8');
    for f = 1:numFrames
        offset = (f - 1) * FRAME_SIZE;
        f_seq(f) = double(typecast(rawData(offset+1:offset+4), 'uint32'));
        e_flag(f) = rawData(offset+5);
    end

    valid_idx = find(e_flag == 0 | e_flag == 1);
    if isempty(valid_idx), continue; end

    valid_seqs = f_seq(valid_idx);

    % GARBAGE FILTER: Detect impossible sequence jumps caused by abrupt power loss on the SD card
    jumps = diff(valid_seqs);
    bad_jump_idx = find(jumps > 500 | jumps < 0, 1, 'first'); 
    if ~isempty(bad_jump_idx)
        valid_seqs = valid_seqs(1:bad_jump_idx); % Slice off the corrupted tail
    end

    validFileCount = validFileCount + 1;
    fileMeta(validFileCount).name = baseFileName;
    fileMeta(validFileCount).data = rawData;
    fileMeta(validFileCount).processed = false;
    fileMeta(validFileCount).start_seq = valid_seqs(1);
    fileMeta(validFileCount).end_seq = valid_seqs(end);
end

% 3. Smart Stitching Algorithm (Absolute Distance Minimizer)
sessions = {};
sessionCount = 0;

while any(~[fileMeta.processed])
    sessionCount = sessionCount + 1;

    unproc_idx = find(~[fileMeta.processed]);
    [~, min_idx] = min([fileMeta(unproc_idx).start_seq]);
    curr_idx = unproc_idx(min_idx);

    current_data = fileMeta(curr_idx).data;
    current_end = fileMeta(curr_idx).end_seq;
    fileMeta(curr_idx).processed = true;

    session_chain = {fileMeta(curr_idx).name};

    while true
        unproc = find(~[fileMeta.processed]);
        if isempty(unproc), break; end

        % Calculate DIRECTIONAL difference (Time must move forward, or slightly backward for PSRAM overlaps)
        diffs = [fileMeta(unproc).start_seq] - current_end;

        % Rule: The next file can overlap by max -5000 frames, or jump forward by max +50000 frames
        valid_mask = diffs > -5000 & diffs < 50000;

        if ~any(valid_mask)
            break; % No candidates fit this session. The session is closed!
        end

        % Among valid candidates, pick the one with the smallest absolute gap
        candidates = unproc(valid_mask);
        cand_diffs = abs(diffs(valid_mask));
        [~, best_idx] = min(cand_diffs);
        next_idx = candidates(best_idx);

        % Stitch it!
        current_data = [current_data; fileMeta(next_idx).data];
        current_end = fileMeta(next_idx).end_seq;
        fileMeta(next_idx).processed = true;
        session_chain{end+1} = fileMeta(next_idx).name;
    end

    sessions{sessionCount}.data = current_data;
    sessions{sessionCount}.chain = session_chain;

    fprintf(' -> Successfully Built Session %d: ', sessionCount);
    fprintf('%s ', session_chain{:});
    fprintf('\n');
end

fprintf('\n==================================================\n');
fprintf('PHASE 2: PAYLOAD DECODING & DIAGNOSTICS\n');
fprintf('==================================================\n');

for s = 1:length(sessions)
    rawData = sessions{s}.data;
    chainNames = strjoin(sessions{s}.chain, ' + ');

    numFrames = floor(length(rawData) / FRAME_SIZE);

    frame_seq = zeros(numFrames, 1, 'uint32');
    event_flag = zeros(numFrames, 1, 'uint8');
    q = nan(numFrames, 4, 'single');        
    acc = nan(numFrames, 3, 'single');      

    for i = 1:numFrames
        offset = (i - 1) * FRAME_SIZE;

        frame_seq(i) = typecast(rawData(offset+1 : offset+4), 'uint32');
        event_flag(i) = rawData(offset+5);

        if event_flag(i) == 0 || event_flag(i) == 1
            q(i, 1) = typecast(rawData(offset+6  : offset+9),  'single'); 
            q(i, 2) = typecast(rawData(offset+10 : offset+13), 'single'); 
            q(i, 3) = typecast(rawData(offset+14 : offset+17), 'single'); 
            q(i, 4) = typecast(rawData(offset+18 : offset+21), 'single'); 

            acc(i, 1) = typecast(rawData(offset+22 : offset+25), 'single'); 
            acc(i, 2) = typecast(rawData(offset+26 : offset+29), 'single'); 
            acc(i, 3) = typecast(rawData(offset+30 : offset+33), 'single'); 
        end
    end

    gap_indices = find(event_flag == 170);
    tag_indices = find(event_flag == 1);

    valid_imu_idx = find(event_flag == 0 | event_flag == 1);
    valid_seq = double(frame_seq(valid_imu_idx));

    % Clean drops visualization by applying the same garbage filter
    jumps = diff(valid_seq);
    clean_jumps = jumps(jumps < 50000 & jumps > 0);
    drop_instances = find(clean_jumps > 1);
    total_dropped_frames = sum(clean_jumps(drop_instances) - 1);

    fprintf('\n[SESSION %d STATS] (%s)\n', s, chainNames);
    fprintf('  - Total Merged Frames: %d\n', numFrames);
    fprintf('  - SD Card Recovery Gaps: %d\n', length(gap_indices));
    fprintf('  - Missing Frames (Queue Drops): %d\n', total_dropped_frames);

    figure('Name', sprintf('Session %d Analysis [%s]', s, chainNames), 'Position', [150+(s*20), 100+(s*20), 1100, 750]);

    subplot(3, 1, 1); hold on; grid on;
    plot(acc(:,1), 'r', 'DisplayName', 'Acc X'); plot(acc(:,2), 'g', 'DisplayName', 'Acc Y'); plot(acc(:,3), 'b', 'DisplayName', 'Acc Z');
    if ~isempty(tag_indices), plot(tag_indices, acc(tag_indices, 3), 'k^', 'MarkerFaceColor', 'y', 'MarkerSize', 7, 'DisplayName', 'Waypoint'); end
    if ~isempty(gap_indices)
        for g = 1:length(gap_indices), xline(gap_indices(g), 'm--', 'LineWidth', 1.8, 'HandleVisibility', 'off'); end
        plot(NaN, NaN, 'm--', 'LineWidth', 1.8, 'DisplayName', 'Recovery Gap');
    end
    title(sprintf('SESSION %d: 3-Axis Acceleration', s)); ylabel('g'); legend('Location', 'best');

    subplot(3, 1, 2); hold on; grid on;
    plot(q(:,1), 'k', 'DisplayName', 'Qw'); plot(q(:,2), 'r', 'DisplayName', 'Qx');
    plot(q(:,3), 'g', 'DisplayName', 'Qy'); plot(q(:,4), 'b', 'DisplayName', 'Qz');
    title('Orientation (Madgwick)'); ylabel('Value'); legend('Location', 'best');

    subplot(3, 1, 3); hold on; grid on;
    plot(valid_imu_idx, valid_seq, 'b-', 'DisplayName', 'Stream');
    if ~isempty(drop_instances), plot(valid_imu_idx(drop_instances), valid_seq(drop_instances), 'ro', 'MarkerFaceColor', 'r', 'DisplayName', 'Data Drop'); end
    title(sprintf('Frame Continuity (Lost: %d)', total_dropped_frames)); xlabel('Merged File Row Index'); ylabel('Frame Seq');
end


% Last Edit: 2026-06-14
% Reason for Last Edit: Upgraded parser to 45-Byte parametric structure.
% Added 64-bit hardware timestamp decoding and temperature extraction.
% Migrated plotting X-axis to absolute time (seconds) for precision analysis.

clc; clear; close all;

% --- HARDWARE ARCHITECTURE CONFIGURATION ---
FRAME_SIZE = 45; % Updated to 45-byte parametric structure 

fprintf('\n==================================================\n');
fprintf('   DEADRECKONER DETERMINISTIC STITCHING PIPELINE   \n');
fprintf('==================================================\n');

% 1. Extract Unique Session IDs (XXX) from directory
allFiles = dir('*.BIN');
if isempty(allFiles)
    fprintf('CRITICAL ERROR: No .BIN log files discovered in directory.\n');
    return;
end

% Extract all 3-digit main log IDs present in the folder
sessionIDs = [];
for f = 1:length(allFiles)
    name = allFiles(f).name;
    % Match DR_LOG_XXX.BIN
    tokens = regexp(name, 'DR_LOG_(\d{3})\.BIN', 'tokens');
    if ~isempty(tokens)
        sessionIDs = [sessionIDs, str2double(tokens{1}{1})];
    else
        % Match XXXXXX.BIN (Recovery Files)
        tokens = regexp(name, '^(\d{3})(\d{3})\.BIN', 'tokens');
        if ~isempty(tokens)
            sessionIDs = [sessionIDs, str2double(tokens{1}{1})];
        end
    end
end
uniqueSessions = unique(sessionIDs);

if isempty(uniqueSessions)
    fprintf('CRITICAL ERROR: No structured logs found matching naming protocols.\n');
    return;
end

% 2. Session-by-Session Chaining and Decoding Loop
for s = 1:length(uniqueSessions)
    currSessionID = uniqueSessions(s);
    sessionData = uint8([]);
    fileChain = {};

    % Step A: Search and load the parent log file if it exists
    parentName = sprintf('DR_LOG_%03d.BIN', currSessionID);
    if exist(parentName, 'file')
        fid = fopen(parentName, 'rb');
        sessionData = [sessionData; fread(fid, inf, '*uint8')];
        fclose(fid);
        fileChain{end+1} = parentName;
    end

    % Step B: Search and load child recovery logs in strict linear order (YYY)
    recoveryID = 1;
    while true
        childName = sprintf('%03d%03d.BIN', currSessionID, recoveryID);
        if exist(childName, 'file')
            fid = fopen(childName, 'rb');
            sessionData = [sessionData; fread(fid, inf, '*uint8')];
            fclose(fid);
            fileChain{end+1} = childName;
            recoveryID = recoveryID + 1;
        else
            break; % Chain broken, no more recovery files for this session
        end
    end

    % Validate session size
    numFrames = floor(length(sessionData) / FRAME_SIZE);
    if numFrames < 2, continue; end

    % 3. Preallocate memory for high-speed extraction (45-Byte Structure)
    frame_seq = zeros(numFrames, 1, 'uint32');
    timestamp_us = zeros(numFrames, 1, 'uint64');
    event_flag = zeros(numFrames, 1, 'uint8');
    q = nan(numFrames, 4, 'single');        
    acc = nan(numFrames, 3, 'single');
    temp = nan(numFrames, 1, 'single');

    % 4. Decode Packed Bytes
    for i = 1:numFrames
        offset = (i - 1) * FRAME_SIZE;

        frame_seq(i)    = typecast(sessionData(offset+1 : offset+4), 'uint32');
        timestamp_us(i) = typecast(sessionData(offset+5 : offset+12), 'uint64');
        event_flag(i)   = sessionData(offset+13);

        if event_flag(i) == 0 || event_flag(i) == 1
            q(i, 1)   = typecast(sessionData(offset+14 : offset+17), 'single'); % Qw
            q(i, 2)   = typecast(sessionData(offset+18 : offset+21), 'single'); % Qx
            q(i, 3)   = typecast(sessionData(offset+22 : offset+25), 'single'); % Qy
            q(i, 4)   = typecast(sessionData(offset+26 : offset+29), 'single'); % Qz

            acc(i, 1) = typecast(sessionData(offset+30 : offset+33), 'single'); % Acc X
            acc(i, 2) = typecast(sessionData(offset+34 : offset+37), 'single'); % Acc Y
            acc(i, 3) = typecast(sessionData(offset+38 : offset+41), 'single'); % Acc Z

            temp(i)   = typecast(sessionData(offset+42 : offset+45), 'single'); % Temperature
        end
    end

    % Convert timestamp to seconds for plotting
    time_sec = double(timestamp_us) / 1e6;

    % --- MATHEMATICAL TRANSFORMATIONS ---
    % Convert Quaternions to standard Euler Angles (Roll, Pitch, Yaw) in Degrees
    roll = nan(numFrames, 1); pitch = nan(numFrames, 1); yaw = nan(numFrames, 1);
    valid_q_idx = find(event_flag == 0 | event_flag == 1);

    for idx = 1:length(valid_q_idx)
        ii = valid_q_idx(idx);
        w = q(ii,1); x = q(ii,2); y = q(ii,3); z = q(ii,4);

        roll(ii)  = atan2(2*(w*x + y*z), 1 - 2*(x^2 + y^2)) * (180/pi);
        pitch(ii) = asin(clamp(2*(w*y - z*x), -1, 1)) * (180/pi);
        yaw(ii)   = atan2(2*(w*z + x*y), 1 - 2*(y^2 + z^2)) * (180/pi);
    end

    % --- ENGINEERING STATS & HEALTH DIAGNOSTICS ---
    gap_indices = find(event_flag == 170); % 0xAA
    tag_indices = find(event_flag == 1);

    valid_seq = double(frame_seq(valid_q_idx));
    jumps = diff(valid_seq);
    drop_instances = find(jumps > 1);
    total_dropped_frames = sum(jumps(drop_instances) - 1);

    % Statistical Signal Metrics
    mean_acc = mean(acc(valid_q_idx, :));
    rms_acc = rms(acc(valid_q_idx, :));

    % Print Engineering Logs to Screen
    chainString = strjoin(fileChain, ' -> ');
    total_time = max(time_sec) - min(time_sec);

    fprintf('\n[✓] SESSION %d REGISTERED MAP:\n', currSessionID);
    fprintf('    [*] Chained Nodes: %s\n', chainString);
    fprintf('    [*] Combined Payload: %d frames (~%.2f seconds)\n', numFrames, total_time);
    fprintf('    [+] User Waypoint Markers Pressed: %d times\n', length(tag_indices));
    fprintf('    [!] Intercepted SD Crashes: %d instances\n', length(gap_indices));
    fprintf('    [!] Memory Drops (Queue Drops): %d frames\n', total_dropped_frames);
    fprintf('    [*] Dynamic Acceleration RMS: [X:%.2f, Y:%.2f, Z:%.2f] g\n', rms_acc(1), rms_acc(2), rms_acc(3));

    % --- ADVANCED PLOTTING ENGINE ---
    figure('Name', sprintf('Session %d Analysis Matrix', currSessionID), 'Position', [100+(s*30), 50+(s*30), 1200, 800]);

    % Subplot 1: Linear Acceleration Profile
    subplot(3, 1, 1); hold on; grid on;
    plot(time_sec, acc(:,1), 'r', 'LineWidth', 1.0, 'DisplayName', 'Acc X'); 
    plot(time_sec, acc(:,2), 'g', 'LineWidth', 1.0, 'DisplayName', 'Acc Y'); 
    plot(time_sec, acc(:,3), 'b', 'LineWidth', 1.0, 'DisplayName', 'Acc Z');

    if ~isempty(tag_indices)
        plot(time_sec(tag_indices), acc(tag_indices, 3), 'k^', 'MarkerFaceColor', 'y', 'MarkerSize', 8, 'DisplayName', 'User Tag');
    end
    if ~isempty(gap_indices)
        for g = 1:length(gap_indices)
            xline(time_sec(gap_indices(g)), 'm--', 'LineWidth', 1.5, 'HandleVisibility', 'off'); 
        end
        plot(NaN, NaN, 'm--', 'LineWidth', 1.5, 'DisplayName', 'SD Crash Link Event');
    end
    title(sprintf('Session %d - 3-Axis Acceleration Profile', currSessionID), 'FontSize', 11);
    ylabel('Acceleration (g)'); legend('Location', 'best');

    % Subplot 2: Physical Attitude Navigation Profile (Euler Angles)
    subplot(3, 1, 2); hold on; grid on;
    plot(time_sec, roll, 'm', 'LineWidth', 1.1, 'DisplayName', 'Roll (\Phi)'); 
    plot(time_sec, pitch, 'c', 'LineWidth', 1.1, 'DisplayName', 'Pitch (\theta)'); 
    plot(time_sec, yaw, 'k', 'LineWidth', 1.3, 'DisplayName', 'Yaw (\Psi)');
    title('Real-World Attitude Extrapolated Data (Euler Degrees)', 'FontSize', 11);
    ylabel('Degrees (\circ)'); legend('Location', 'best');

    % Subplot 3: Stream Quality & Time-Continuity Monitor
    subplot(3, 1, 3); hold on; grid on;
    plot(valid_q_idx, valid_seq, 'b-', 'LineWidth', 1.2, 'DisplayName', 'Sequence Stream');
    if ~isempty(drop_instances)
        plot(valid_q_idx(drop_instances), valid_seq(drop_instances), 'ro', 'MarkerFaceColor', 'r', 'DisplayName', 'Buffer Overflow');
    end
    title(sprintf('Timeline Stream Continuity Quality (Total Drops: %d frames)', total_dropped_frames), 'FontSize', 11);
    xlabel('Global Merged Row Index (Samples @ 100Hz)'); ylabel('MCU Counter Value');
    legend('Location', 'northwest');
end

% Helper clipping function to safe-guard asin calculation from floating errors
function out = clamp(in, minVal, maxVal)
    out = min(max(in, minVal), maxVal);
end


// Last Edit: 2026-06-03 15:27:00
// Reason for Last Edit: Added comprehensive wiring diagram and project metadata
// Author: Alireza Sotoodeh

/*
 * =========================================================================
 * PROJECT: Dead Reckoner Project
 * VERSION: 1.0 (Prototype)
 * * WIRING DIAGRAM
 * -------------------------------------------------------------------------
 * Component        | ESP8266 (NodeMCU) Pin | Note / Reasoning
 * -------------------------------------------------------------------------
 * MPU9250 VCC      | 3.3V                  | MPU9250 is 3.3V tolerant logic
 * MPU9250 GND      | GND                   | Common ground
 * MPU9250 SCL      | D1 (GPIO 5)           | Hardware I2C Clock for fast IMU reads
 * MPU9250 SDA      | D2 (GPIO 4)           | Hardware I2C Data for fast IMU reads
 * -------------------------------------------------------------------------
 * OLED VCC         | 3.3V                  | 
 * OLED GND         | GND                   | Common ground
 * OLED SCL         | D4 (GPIO 2)           | Software I2C to avoid bus congestion
 * OLED SDA         | D3 (GPIO 0)           | Software I2C with the IMU
 * -------------------------------------------------------------------------
 * Push Button      | D5 (GPIO 14)          | Input Pullup; Connects to GND when pressed
 * -------------------------------------------------------------------------
 * * DESIGN NOTES:
 * - OLED is intentionally separated onto Software I2C to prevent display 
 * updates from blocking high-speed sensor fusion reads from the MPU9250.
 * =========================================================================
 */

/*////////////////////////////includes////////////////////////////*/
#include "MPU9250.h" //for setting up MPU9250
#include <EEPROM.h>  // ESP8266 EEPROM library for loading calibration
#include <U8g2lib.h> // U8g2 library for OLED
/*////////////////////////////defines////////////////////////////*/
#define bud_rate 115200
//pins
#define BUTTON_PIN 14             											// Push button on D5 (GPIO 14) for NodeMCU
//MpU9205
#define MPU9250_IMU_ADDRESS 0x68 												// Specifies the I2C slave address of the MPU9250:0x68 GND / 0x69 High
#define MAGNETIC_DECLINATION 3.4	 											// angle between magnetic north and true north
#define INTERVAL_MS_PRINT 50 														// Sets the minimum time interval between printing sensor data in the loop to avoid flooding the serial output. higher measn slower 
MPU9250 mpu; 																						// handler: allowing access to all library methods
unsigned long lastPrintMillis = 0; 											// Tracks the timestamp (from millis()) of the last time sensor data was printed to Serial

//MPU9250 setting
#define MPU9250_Accelerometer_Rang  A2G 								//select: A2G, A4G, A8G, A16G
#define MPU9250_Gyroscope_Rang  G500DPS 								//select: G250DPS, G500DPS, G1000DPS, G2000DPS
#define MPU9250_Magnetometer_resolution  M16BITS 				//select: M14BITS, M16BITS
#define MPU9250_fifo_sample_rate  SMPL_1000HZ 					//select: SMPL_1000HZ, SMPL_500HZ, SMPL_333HZ, SMPL_250HZ, SMPL_200HZ, SMPL_167HZ, SMPL_143HZ, SMPL_125HZ
#define MPU9250_Gyroscope_filter_choice  0x01						//select: 0x00: Enables DLPF with 8kHz sample rate. 0x01: Enables DLPF with 1kHz sample rate. 0x02 or 0x03: Bypasses DLPF
#define MPU9250_Gyroscope_DLPF_cutoff  DLPF_5HZ 				//select: DLPF_250HZ, DLPF_184HZ, DLPF_92HZ, DLPF_41HZ, DLPF_20HZ, DLPF_10HZ, DLPF_5HZ, DLPF_3600HZ
#define MPU9250_Accelerometer_filter_choice  0x01				//select: 0x01 Enable, 0x00 bypass
#define MPU9250_Accelerometer_DLPF_cutoff  DLPF_5HZ 		//select: DLPF_218HZ_0, DLPF_218HZ_1, DLPF_99HZ, DLPF_45HZ, DLPF_21HZ, DLPF_10HZ, DLPF_5HZ, DLPF_420HZ
#define MPU9250_filter_algorithm	MADGWICK 							//select: MADGWICK, MAHONY, NONE
#define MPU9250_filter_iterations	10										//select: 1-50 higher better but may slow down

// OLED setup (0.91-inch SSD1306, 128x32, Software I2C on D3, D4)
U8G2_SSD1306_128X32_UNIVISION_F_SW_I2C u8g2(U8G2_R0, /* clock=*/ 2, /* data=*/ 0, /* reset=*/ U8X8_PIN_NONE); // Software I2C on D4 (SCL, GPIO 2), D3 (SDA, GPIO 0)
#define font_10_pixel u8g2_font_t0_15b_me
#define font_8_pixel u8g2_font_helvB08_tf
#define font_5_pixel u8g2_font_spleen5x8_me
#define update_rate_oled 1500
/*////////////////////////////setup////////////////////////////*/
void setup() 
{ 
	Serial.begin(bud_rate); 
	Wire.begin(); // Hardware I2C for MPU9250 on D1 (SCL, GPIO 5), D2 (SDA, GPIO 4)
	pinMode(BUTTON_PIN, INPUT_PULLUP);	 // Button with internal pull-up (active-low)
  // Initialize OLED
  u8g2.begin();
  u8g2.clearBuffer();
  u8g2.setFont(font_10_pixel);   
  u8g2.drawStr(15, 25, "<< Boot up >>");
  u8g2.sendBuffer();
  delay(1000);
  u8g2.setFont(font_8_pixel); 
	MPU9250Setting setting;
	// Initialize MPU9250 
	// Sample rate must be at least 2x DLPF rate 
	setting.accel_fs_sel = ACCEL_FS_SEL::MPU9250_Accelerometer_Rang; 
	setting.gyro_fs_sel = GYRO_FS_SEL::MPU9250_Gyroscope_Rang; 
	setting.mag_output_bits = MAG_OUTPUT_BITS::MPU9250_Magnetometer_resolution; 
	setting.fifo_sample_rate = FIFO_SAMPLE_RATE::MPU9250_fifo_sample_rate; 
	setting.gyro_fchoice = MPU9250_Gyroscope_filter_choice; 
	setting.gyro_dlpf_cfg = GYRO_DLPF_CFG::MPU9250_Gyroscope_DLPF_cutoff; 
	setting.accel_fchoice = MPU9250_Accelerometer_filter_choice; 
	setting.accel_dlpf_cfg = ACCEL_DLPF_CFG::MPU9250_Accelerometer_DLPF_cutoff; 
	//start to setup the MPU based on setting and address
  while (!mpu.setup(MPU9250_IMU_ADDRESS, setting)) {
    Serial.println("MPU connection failed. Retrying in 5 seconds...");
    u8g2.clearBuffer();
    u8g2.drawStr(20, 15, "MPU9250 Failed!");
    u8g2.drawStr(20, 28, "Retrying...");
   u8g2.sendBuffer();
    delay(5000); 
  }							
	mpu.setMagneticDeclination(MAGNETIC_DECLINATION); 
	mpu.selectFilter(QuatFilterSel::MPU9250_filter_algorithm); 
	mpu.setFilterIterations(MPU9250_filter_iterations);

	// Initialize EEPROM for ESP8266
  #if defined(ESP_PLATFORM) || defined(ESP8266)
    EEPROM.begin(0x80);  // Allocate 128 bytes for EEPROM
  #endif
 	// Load calibration from EEPROM on startup
  Serial.println("Loading calibration from EEPROM...");
  u8g2.clearBuffer();
  u8g2.drawStr(25, 20, "Loading calibration");
  u8g2.drawStr(35, 30, "from EEPROM");
  u8g2.sendBuffer();
  loadCalibration();
  print_calibration();
  u8g2.clearBuffer();
  u8g2.drawStr(25, 15, "Press Button");
  u8g2.drawStr(35, 25, "to Calibrate");
  u8g2.sendBuffer();
  u8g2.setFont(font_5_pixel); 
} 
/*////////////////////////////loop////////////////////////////*/

void loop() 
{ 
	// Check for button press (active-low)
  if (digitalRead(BUTTON_PIN) == LOW) {
    delay(50);  // Debounce delay
    if (digitalRead(BUTTON_PIN) == LOW) {  // Confirm button press
      u8g2.setFont(font_8_pixel); 
      Serial.println("Button pressed. Starting calibration...");
      u8g2.clearBuffer();
      u8g2.drawStr(25, 15, "Calibrating...");
      u8g2.sendBuffer();
      performCalibration();
      saveCalibration();
      print_calibration();
      Serial.println("Calibration saved to EEPROM. Press button to recalibrate.");
      u8g2.clearBuffer();
      u8g2.drawStr(25, 15, "Calibration Done");
      u8g2.drawStr(25, 25, "Press to Recal");
      u8g2.sendBuffer();
      u8g2.setFont(font_5_pixel); 
      while (digitalRead(BUTTON_PIN) == LOW) {
        delay(10);  // Wait for button release
      }
    }
  }
  // Main sensor data loop
  unsigned long currentMillis = millis();
  if (mpu.update() && currentMillis - lastPrintMillis > INTERVAL_MS_PRINT) {
    // Get quaternions and accelerations
    float qw = mpu.getQuaternionW();
    float qx = mpu.getQuaternionX();
    float qy = mpu.getQuaternionY();
    float qz = mpu.getQuaternionZ();
    float ax = mpu.getLinearAccX();  // Acceleration in m/s²
    float ay = mpu.getLinearAccY();
    float az = mpu.getLinearAccZ();
    float temp = mpu.getTemperature();

    // Print to Serial for MATLAB (qw,qx,qy,qz,ax,ay,az)
    Serial.print(qw, 6); Serial.print(",");
    Serial.print(qx, 6); Serial.print(",");
    Serial.print(qy, 6); Serial.print(",");
    Serial.println(qz, 6);/* Serial.print(",");
    Serial.print(ax, 6); Serial.print(",");
    Serial.print(ay, 6); Serial.print(",");
    Serial.println(az, 6);*/

    // Display on OLED (rotate quaternions and accelerations every 2 seconds)
    static unsigned long lastDisplayMillis = 0;
    static bool showQuaternions = true;
    if (currentMillis - lastDisplayMillis > update_rate_oled) {
      u8g2.clearBuffer();

        char buf[32];
        snprintf(buf, sizeof(buf), "Qw: %.3f", qw);
        u8g2.drawStr(0, 7, buf);
        snprintf(buf, sizeof(buf), "Qx: %.3f", qx);
        u8g2.drawStr(0, 15, buf);
        snprintf(buf, sizeof(buf), "Qy: %.3f", qy);
        u8g2.drawStr(64, 7, buf);
        snprintf(buf, sizeof(buf), "Qz: %.3f", qz);
        u8g2.drawStr(64, 15, buf);
        snprintf(buf, sizeof(buf), "Ax: %.2f", ax);
        u8g2.drawStr(0, 23, buf);
        snprintf(buf, sizeof(buf), "Ay: %.2f", ay);
        u8g2.drawStr(0, 31, buf);
        snprintf(buf, sizeof(buf), "Az: %.2f", az);
        u8g2.drawStr(64, 23, buf);
        snprintf(buf, sizeof(buf), "temp: %.2f", temp);
        u8g2.drawStr(64, 31, buf);

      u8g2.sendBuffer();
      lastDisplayMillis = currentMillis;
    }

    lastPrintMillis = currentMillis;
  }
} 

