// Reason for Last Edit: Standalone Sanity Check for SPI SD Card Module on Arduino Nano
// Last Edit: 2026-06-05 01:10:00
// Reason for Last Edit: Added wiring diagram for Arduino Nano SPI connections.
// Author: Alireza Sotoodeh

/*
 * =========================================================================
 * PROJECT: Hardware Sanity Check (SD Card Module)
 * VERSION: Test.3
 * * WIRING DIAGRAM
 * -------------------------------------------------------------------------
 * Component        | Arduino Nano Pin      | Note / Reasoning
 * -------------------------------------------------------------------------
 * SD Card VCC      | 5V                    | Module requires 5V logic power
 * SD Card GND      | GND                   | Common ground
 * SD Card CS       | D10                   | SPI Chip Select
 * SD Card MOSI     | D11                   | SPI Master Out Slave In
 * SD Card MISO     | D12                   | SPI Master In Slave Out
 * SD Card SCK      | D13                   | SPI Serial Clock
 * -------------------------------------------------------------------------
 * * DESIGN NOTES:
 * - This code explicitly tests the SPI interface, file creation, block writing, 
 * and reading capabilities of the SD Card module before integration into the 
 * main dual-core ESP32-S3 architecture.
 * =========================================================================
 */

#include <SPI.h>
#include <SD.h>

const int chipSelect = 10;
File dataFile;

void setup() {
  Serial.begin(115200);
  while (!Serial) {
    ; // Wait for serial port to connect
  }

  Serial.println("=================================");
  Serial.println("Starting SD Card Sanity Check...");
  Serial.println("=================================");

  // Initialize the SD card
  Serial.print("STATUS: Initializing SD card... ");
  if (!SD.begin(chipSelect)) {
    Serial.println("FAILED!");
    Serial.println("ERROR: Check wiring, ensure SD card is inserted and formatted to FAT32.");
    while (1); // Halt the system
  }
  Serial.println("SUCCESS.");

  // Test 1: File Creation and Writing
  Serial.print("STATUS: Opening test.txt for writing... ");
  dataFile = SD.open("test.txt", FILE_WRITE);

  if (dataFile) {
    Serial.println("SUCCESS.");
    Serial.println("STATUS: Writing test data block...");
    dataFile.println("SD Card Sanity Check Passed.");
    dataFile.println("Module is ready for DeadReckoner Phase 3.");
    dataFile.close();
    Serial.println("STATUS: File closed and data flushed to memory.");
  } else {
    Serial.println("FAILED to open test.txt for writing.");
    while (1); // Halt
  }

  // Test 2: File Reading and Verification
  Serial.print("STATUS: Re-opening test.txt for reading... ");
  dataFile = SD.open("test.txt");

  if (dataFile) {
    Serial.println("SUCCESS.");
    Serial.println("--- DATA READ FROM SD CARD ---");
    while (dataFile.available()) {
      Serial.write(dataFile.read());
    }
    Serial.println("------------------------------");
    dataFile.close();
    Serial.println("STATUS: Read test completed successfully.");
  } else {
    Serial.println("FAILED to open test.txt for reading.");
  }

  Serial.println("=================================");
  Serial.println("ALL TESTS PASSED. Hardware is healthy.");
  Serial.println("=================================");
}

void loop() {
  // Standalone test does not require loop execution
}


#!/usr/bin/env python3
"""
project_summarizer.py — Interactive project documentation generator.

Generates plain-text (human-friendly) and LLM-optimized Markdown reports:
  - Git commit history (hash, date, author, full message)
  - Directory structure (tree view)
  - Project overview (from README, requirements, etc.)
  - Code analysis (function/class signatures, import graph, configs)
"""

import os
import re
import sys
import ast
import subprocess
import xml.sax.saxutils
from datetime import datetime
from pathlib import Path
from collections import Counter, defaultdict

try:
    import tiktoken
    _HAS_TIKTOKEN = True
except ImportError:
    _HAS_TIKTOKEN = False

try:
    from rich.console import Console
    from rich.panel import Panel
    from rich.progress import Progress, SpinnerColumn, TextColumn
    from rich.rule import Rule
except ImportError:
    print("This script requires 'rich'. Install with: pip install rich")
    sys.exit(1)

try:
    import questionary
except ImportError:
    print("This script requires 'questionary'. Install with: pip install questionary")
    sys.exit(1)

console = Console()
RS = "\x1e"
US = "\x1f"

# ═══════════════════════════════════════════════════════════
# DATA EXTRACTION — CORE
# ═══════════════════════════════════════════════════════════

def check_git_repo(path="."):
    try:
        subprocess.run(["git", "rev-parse", "--git-dir"], cwd=path, capture_output=True, check=True)
        return True
    except (subprocess.CalledProcessError, FileNotFoundError):
        return False


def get_git_commits(max_count=None, path="."):
    cmd = ["git", "log", "--all", f"--format={RS}%H{US}%ai{US}%an{US}%B{RS}", "--no-color"]
    if max_count is not None:
        cmd.extend(["--max-count", str(max_count)])
    result = subprocess.run(cmd, cwd=path, capture_output=True, text=True)
    if result.returncode != 0:
        console.print("[red]Failed to retrieve git log.[/red]")
        return []
    commits = []
    for record in result.stdout.split(RS):
        record = record.strip()
        if not record:
            continue
        fields = record.split(US)
        if len(fields) >= 4:
            commits.append({
                "hash": fields[0][:7],
                "date": fields[1],
                "author": fields[2],
                "message": fields[3].strip(),
            })
    return commits


def build_tree_dict(root_dir, exclude_dirs=None):
    if exclude_dirs is None:
        exclude_dirs = {".git", "__pycache__", ".venv", "venv", ".egg-info",
                        "node_modules", ".mypy_cache", ".pytest_cache", ".tox", ".idea", ".vscode"}
    root = Path(root_dir).resolve()
    tree = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in exclude_dirs]
        rel = Path(dirpath).relative_to(root)
        current = tree
        if rel != Path("."):
            for part in rel.parts:
                current = current[part]
        for d in sorted(dirnames):
            current[d] = {}
        for f in sorted(filenames):
            current[f] = None
    return tree


def render_tree_text(tree, root_name="", prefix=""):
    lines = []
    if root_name:
        lines.append(root_name + "/")
    items = list(tree.items())
    for i, (name, subtree) in enumerate(items):
        is_last = i == len(items) - 1
        conn = "└── " if is_last else "├── "
        display = name + "/" if isinstance(subtree, dict) else name
        lines.append(prefix + conn + display)
        if isinstance(subtree, dict) and subtree:
            ext = "    " if is_last else "│   "
            lines.extend(render_tree_text(subtree, "", prefix + ext))
    return lines


def get_file_stats(root_dir):
    root = Path(root_dir).resolve()
    ext_counts = Counter()
    total_lines = 0
    total_files = 0
    skip = {".git", "__pycache__", ".venv", "venv", ".egg-info", "node_modules", ".mypy_cache", ".pytest_cache"}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in skip]
        for f in filenames:
            total_files += 1
            ext = Path(f).suffix or "(no ext)"
            ext_counts[ext] += 1
            try:
                total_lines += sum(1 for _ in open(Path(dirpath) / f, "r", encoding="utf-8", errors="ignore"))
            except Exception:
                pass
    return total_files, total_lines, ext_counts


def parse_readme(root_dir):
    for p in Path(root_dir).glob("README*"):
        sections = defaultdict(str)
        current = "general"
        content = p.read_text(encoding="utf-8", errors="ignore")
        title = re.search(r"^# (.+)$", content, re.MULTILINE)
        title = title.group(1).strip() if title else ""
        for line in content.split("\n"):
            m = re.match(r"^## (.+)$", line)
            if m:
                current = m.group(1).strip().lower()
            else:
                sections[current] += line + "\n"
        for k in sections:
            sections[k] = sections[k].strip()
        result = {"title": title}
        result.update(sections)
        return result
    return {}


def parse_requirements(root_dir):
    for fname in ("requirements.txt", "requirements.in"):
        p = Path(root_dir) / fname
        if p.exists():
            deps = []
            for line in p.read_text(encoding="utf-8", errors="ignore").split("\n"):
                line = line.strip()
                if line and not line.startswith("#") and not line.startswith("-"):
                    deps.append(line)
            return deps
    return []


